style.css:
@-moz-document domain("roblox.com") {
/* 1. FORCE THE CLASSIC RED 2016 LOGO */
    .icon-logo, .icon-logo-r, .logo {
        background-image: url("https://rbxcdn.com") !important;
        background-position: 0 0 !important;
        background-size: contain !important;
        width: 120px !important;
        height: 30px !important;
    }

    /* 2. RESTORE THE GREEN 2016 ROBUX ICON */
    .icon-robux, .icon-robux-28x28, .icon-robux-gray-16x16 {
        background-image: url("https://rbxcdn.com") !important;
        background-position: center !important;
        background-size: contain !important;
        filter: none !important; /* Removes modern grey filtering */
    }

    /* 3. SET OVERALL 2016 LEGACY DARK BACKGROUND */
    body, .container-main, .content {
        background-color: #2c2d30 !important;
        color: #e8e8e8 !important;
    }

    /* 4. CLASSIC 2016 BLUE/DARK HEADER NAVIGATION */
    .rbx-header {
        background-color: #191b1d !important;
        border-bottom: 2px solid #0074bd !important;
        height: 50px !important;
    }

    /* 5. LEFT SIDEBAR NAVIGATION STYLING */
    #navigation {
        background-color: #222426 !important;
        border-right: 1px solid #151718 !important;
    }

    .left-col-list li a {
        color: #cbd3d6 !important;
        font-family: "Lucida Sans Unicode", "Lucida Grande", sans-serif !important;
    }

    .left-col-list li:hover {
        background-color: #0074bd !important;
    }

    /* 6. OLD-SCHOOL RECTANGULAR GAME CARDS */
    .game-card-container, .item-card-container {
        background-color: #222426 !important;
        border: 1px solid #3a3d42 !important;
        border-radius: 0px !important; /* Removes modern rounded edges */
        padding: 8px !important;
    }

    /* 7. RETRO BUTTON GRADIENETS */
    .btn-to-all, .btn-medium {
        background-color: #0074bd !important;
        background-image: linear-gradient(to bottom, #0084ff, #005ca3) !important;
        border: 1px solid #004b85 !important;
        color: #ffffff !important;
        border-radius: 3px !important;
    }
}
